export function addTranslations(entries) {
  for (const [source, target] of Object.entries(entries)) english.set(source, target);
}

export function preference(key, fallback) {
  try { return localStorage.getItem("rokh-" + key) ?? fallback; }
  catch { return fallback; }
}

export function savePreference(key, value) {
  try { localStorage.setItem("rokh-" + key, value); }
  catch { /* Browser may disable storage. */ }
}

export let language = "fa";
export function setLanguage(value) {
  language = value === "en" ? "en" : "fa";
  document.documentElement.lang = language;
  document.documentElement.dir = language === "fa" ? "rtl" : "ltr";
  document.title = tr("meowd me | تحلیل حالت چهره");
}
export function tr(text) {
  return language === "en" ? english.get(text) ?? text : text;
}

